use std::collections::HashMap;

pub fn index(words: &[&str]) -> HashMap<String, usize> {
    let mut map = HashMap::new();
    for (i, w) in words.iter().enumerate() {
        map.insert((*w).to_string(), i);
    }
    map
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn indexes() {
        let m = index(&["a", "b"]);
        assert_eq!(m.get("a"), Some(&0));
    }
}
